function slide(){if(player.grounded&&Math.hypot(player.vel.x,player.vel.z)>4){player.slide=.9;player.vel.x*=1.15;player.vel.z*=1.15;}else input.crouch=!input.crouch;}
function checkWin(){if(!match||appState!=='game')return;if(match.mode==='Survival'){if(bots.every(b=>!b.alive)){match.wave++;if(match.wave>5){endMatch(true);return;}for(const b of bots){scene.remove(b.mesh);}bots=[];createBots(Math.min(5+match.wave*2,18));player.health=Math.min(100,player.health+25);player.grenades=Math.min(3,player.grenades+1);feed('WAVE '+match.wave+' · incoming');}return;}
if(match.mode==='Training Range')return;if(match.mode==='Gun Game'&&bots.some(b=>b.kills>=8)){endMatch(false);return;}if(match.teamMode){if(match.scores[0]>=match.limit||match.scores[1]>=match.limit)endMatch(match.scores[0]>match.scores[1]);}else if(match.mode!=='Gun Game'){let leader=player.kills;for(const b of bots)leader=Math.max(leader,b.kills);if(leader>=match.limit)endMatch(player.kills>=match.limit);}}
function startMatch(){window.FZApp?.enterFullscreen();AudioManager.init();readConfig();$('#menu').hidden=true;$('#panel').hidden=true;$('#results').hidden=true;$('#loading').hidden=false;appState='loading';setTimeout(()=>{try{buildWorld(MAPS.indexOf(save.config.map),Number(save.config.seed));scene.remove(preview);match={mode:save.config.mode,teamMode:['Team Deathmatch','Custom Match','Sniper Only'].includes(save.config.mode),scores:[0,0],limit:Number(save.config.limit),remaining:Number(save.config.duration),duration:Number(save.config.duration),wave:1};Object.assign(player,{kills:0,deaths:0,headshots:0,damage:0,shots:0,hits:0,longest:0,tier:0,alive:true});appState='game';spawnPlayer();createBots(match.mode==='Training Range'?8:match.mode==='Survival'?7:Number(save.config.bots));$('#loading').hidden=true;$('#hud').hidden=false;$('#pause').hidden=true;$('#feed').textContent='';applyLayout();toast(match.mode==='Training Range'?'Test weapons on static and moving targets. End from Pause.':'Stay mobile. Control the lanes.');}catch(e){fatal(e);$('#loading').hidden=true;}},70);}
function endMatch(won){if(appState!=='game')return;appState='results';input.fire=false;input.ads=false;$('#hud').hidden=true;$('#pause').hidden=true;document.exitPointerLock?.();const earned=Math.round(player.kills*55+player.damage*.06+(won?200:80));save.xp+=earned;save.stats.kills+=player.kills;save.stats.deaths+=player.deaths;save.stats.matches++;save.stats.wins+=won?1:0;save.stats.shots+=player.shots;save.stats.hits+=player.hits;save.history.push({mode:match.mode,map:save.config.map,kills:player.kills,deaths:player.deaths,won,xp:earned,date:Date.now()});save.history=save.history.slice(-20);persist();$('#results').hidden=false;$('#resultTitle').textContent=match.mode==='Training Range'?'RANGE REPORT':won?'VICTORY':'DEFEAT';$('#resultDetails').innerHTML=`<div><strong>${player.kills}</strong>ELIMINATIONS</div><div><strong>${player.deaths}</strong>DEATHS</div><div><strong>${Math.round(player.hits/Math.max(1,player.shots)*100)}%</strong>HIT RATE*</div><div><strong>${player.headshots}</strong>HEADSHOTS</div><div><strong>${Math.round(player.damage)}</strong>DAMAGE</div><div><strong>${Math.round(player.longest)}m</strong>LONGEST KILL</div>`;$('#resultXP').textContent=`+${earned} XP · LEVEL ${1+Math.floor(save.xp/1000)} · ${Math.round(match.duration-match.remaining)} seconds`;}
function goMenu(){appState='menu';$('#hud').hidden=true;$('#pause').hidden=true;$('#results').hidden=true;$('#panel').hidden=true;$('#menu').hidden=false;weaponRoot.visible=false;document.exitPointerLock?.();input.fire=input.ads=false;clearEffects();buildWorld(MAPS.indexOf(save.config.map),Number(save.config.seed));updateProfile();}
