function selectOptions(arr,value){return arr.map((v,i)=>`<option value="${typeof v==='string'?v:i}" ${value===(typeof v==='string'?v:i)?'selected':''}>${typeof v==='string'?v:v.name}</option>`).join('');}
function configHTML(){const c=save.config;return `<div class="formgrid"><label>Operation<select id="cfgMode">${selectOptions(MODES,c.mode)}</select></label><label>Arena<select id="cfgMap">${selectOptions(MAPS,c.map)}</select></label><label>Difficulty<select id="cfgDifficulty">${selectOptions(['Recruit','Regular','Veteran','Elite'],c.difficulty)}</select></label><label>Opponents / allies<select id="cfgBots">${selectOptions([2,4,6,8,10,12].map(String),String(c.bots))}</select></label><label>Score limit<input id="cfgLimit" type="number" min="5" max="100" value="${c.limit}"></label><label>Seconds<input id="cfgDuration" type="number" min="30" max="900" value="${c.duration}"></label><label>Weather<select id="cfgWeather">${selectOptions(['Clear','Cloudy','Rain','Dense fog','Snow','Sandstorm'],c.weather)}</select></label><label>Lighting<select id="cfgTime">${selectOptions(['Midday','Sunset','Night','Dynamic'],c.time)}</select></label><label>Map seed<input id="cfgSeed" type="number" value="${c.seed}"></label></div><p class="muted">Two teams in TDM, Sniper Only and Custom. Survival: clear five waves. Gun Game: earn eight weapon-tier eliminations. The range ends when you select End match.</p>`;}
function readConfig(){if($('#cfgMode')){const fields={mode:'Mode',map:'Map',difficulty:'Difficulty',bots:'Bots',limit:'Limit',duration:'Duration',weather:'Weather',time:'Time',seed:'Seed'};for(const [key,id] of Object.entries(fields))save.config[key]=$('#cfg'+id).value;save.config.bots=clamp(+save.config.bots,2,12);save.config.limit=clamp(+save.config.limit||20,5,100);save.config.duration=clamp(+save.config.duration||180,30,900);save.config.seed=+save.config.seed||2026;}persist();}
