function lobby(){panel('DEPLOYMENT',`<p class="eyebrow">OFFLINE OPERATIONS / PROCEDURAL ARENAS</p>${configHTML()}<button class="primary" id="deploy">DEPLOY NOW <span>→</span></button><p class="muted">Desktop: WASD · Mouse aim · Space jump · Shift sprint · Ctrl crouch · C slide · R reload · X / 2 swap · RMB / Z ADS · Q / E peek · G grenade · V melee · Esc pause. Touch: left stick + right-side drag; action buttons support multiple pointers.</p>`);$('#deploy').onclick=startMatch;}
function loadout(){panel('ARMORY',`<div class="formgrid"><label>Primary<select id="primary">${selectOptions(WEAPONS,save.loadout.primary)}</select></label><label>Secondary<select id="secondary">${selectOptions(WEAPONS.filter(w=>w.type==='pistol').map(w=>w.name),WEAPONS[save.loadout.secondary].name)}</select></label><label>Attachment<select id="attachment">${selectOptions(['Red dot','4x scope','Suppressor','Compensator','Extended mag','Vertical grip'],save.loadout.attachment)}</select></label></div><p class="muted">Compensator: 30% less recoil. Grip: 20% less spread. Extended magazine: 30% more rounds. The 4x optic magnifies ADS. Suppressor changes the weapon mesh; sound suppression is not yet simulated.</p><div id="weaponCards" class="cards"></div><p class="muted">Release 1 includes these eight firearms and a combat knife. All are unlocked for testing. Mastery tracks eliminations offline.</p>`);function apply(){save.loadout.primary=+$('#primary').value;save.loadout.secondary=WEAPONS.findIndex(w=>w.name===$('#secondary').value);save.loadout.attachment=$('#attachment').value;persist();cards();}function cards(){$('#weaponCards').innerHTML=WEAPONS.map((w,i)=>`<div class="card ${save.loadout.primary===i?'selected':''}"><small>${w.type.toUpperCase()}</small><h3>${w.name}</h3><p>${w.mag} ROUNDS · ${Math.round(60/w.rate)} RPM</p><p>MASTERY ${save.mastery[i]||0}</p></div>`).join('');}$('#primary').onchange=$('#secondary').onchange=$('#attachment').onchange=apply;cards();}
function settings(){const s=save.settings;panel('SYSTEMS',`<div class="formgrid"><label>Input mode<select data-setting="inputMode">${selectOptions(['Auto','Keyboard / mouse','Touch'],s.inputMode)}</select></label><label>Graphics<select data-setting="quality">${selectOptions(['Ultra Low','Low','Balanced','High','Ultra','Automatic'],s.quality)}</select></label><label>Resolution <input data-setting="scale" type="range" min=".4" max="1" step=".05" value="${s.scale}"></label><label>Field of view<input data-setting="fov" type="range" min="65" max="105" value="${s.fov}"></label><label>Look sensitivity<input data-setting="sensitivity" type="range" min=".2" max="3" step=".1" value="${s.sensitivity}"></label><label>ADS sensitivity<input data-setting="adsSensitivity" type="range" min=".1" max="1.5" step=".05" value="${s.adsSensitivity}"></label><label>Master volume<input data-setting="volume" type="range" min="0" max="1" step=".05" value="${s.volume}"></label>${['autoHop','autoSprint','assist','shake','invert','fps','bloom'].map(k=>`<label class="check"><input data-setting="${k}" type="checkbox" ${s[k]?'checked':''}>${{autoHop:'Automatic bunny hop',autoSprint:'Automatic sprint',assist:'Touch aim slowdown',shake:'Camera shake',invert:'Invert vertical look',fps:'Performance diagnostics',bloom:'Atmospheric bloom'}[k]}</label>`).join('')}</div><div class="buttonrow"><button id="editHUD">EDIT TOUCH HUD</button><button id="exportSave">EXPORT SAVE</button><label class="button">IMPORT SAVE<input type="file" id="importSave" accept="application/json" hidden></label><button id="resetSave">RESET PROGRESS</button></div><p class="muted">Graphics presets affect render resolution, shadows, particle budget and view distance. Automatic adjusts resolution based on frame time. File-browser storage support varies; export your save before moving or renaming this file.</p>`);
for(const e of document.querySelectorAll('[data-setting]'))e.onchange=()=>{save.settings[e.dataset.setting]=e.type==='checkbox'?e.checked:e.tagName==='SELECT'?e.value:+e.value;renderScale=save.settings.scale;applyQuality();detectInput();persist();};$('#editHUD').onclick=()=>{$('#panel').hidden=true;if(appState==='menu'){match={mode:'Training Range',teamMode:false};appState='editor';$('#panel').hidden=true;$('#hud').hidden=false;}editing=true;$('#editor').hidden=false;$('#hud').classList.add('editing');applyLayout();};$('#exportSave').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(save,null,2)],{type:'application/json'}));a.download='frontline-zero-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};$('#importSave').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(data.version!==1||!data.settings||!data.stats||!data.loadout)throw Error('Unsupported save');const restored=structuredClone(defaults);for(const k of ['xp','stats','mastery','history','loadout','settings','layout','config'])if(data[k]!=null)restored[k]=data[k];restored.settings={...defaults.settings,...restored.settings};restored.config={...defaults.config,...restored.config};restored.loadout.primary=clamp(+restored.loadout.primary||0,0,7);restored.loadout.secondary=clamp(+restored.loadout.secondary||6,6,7);restored.xp=Math.max(0,+restored.xp||0);save=restored;validateSave();persist();toast('Save imported');settings();}catch(e){toast('Import rejected: '+e.message);}};$('#resetSave').onclick=()=>{if(confirm('Reset progression, settings and loadout?')){save=structuredClone(defaults);persist();settings();toast('Save reset');}};}
